#include <stdio.h>
#include <string.h>
typedef unsigned int U; typedef int I; typedef unsigned long Q;
typedef U nslSourceId; typedef U nslSoundId; typedef U nslEmitterId;
typedef float M[4][4] __attribute__((aligned(16))); typedef float V[3];
#define NSL_NUM_SOURCES 512
#define NSL_NUM_SOUNDS 256
#define NSL_NUM_EMITTERS 256
enum nslSourceTypeEnum { ST };
enum nslSpeakerModeEnum { SM };
enum nslOutputModeEnum { OM };
enum nslLanguageEnum { EN, FR, DE, ES, IT, JP, NSL_LANGUAGE_Z };
enum nslPs2CdDvdMode { CD };
enum _nslClearBehaviour { NSL_CLEAR_INIT, NSL_CLEAR_RESET, NSL_CLEAR_FREE };
template<class T> class fifo_queue { T *q; short m,s,e,c; };
struct nslSource {
  bool used,looping; char fileName[48]; int bank; nslSourceId myId;
  float length,paddedLength; nslSourceTypeEnum type; U gasSourceId;
  float rawVolume,pitch,minDist,maxDist;
};
struct nslSound {
  bool isReady,used,inRange,isReallyReady,isPlaying,isReallyPlaying,looping,isQueuing;
  short left,right,old_left,old_right; U gasInstanceId; I pauseCount,dampenCount;
  nslSourceId myId,mySource; nslEmitterId myEmitter;
  float rawVolume,positionalVolume,angle,pitch,minDist,maxDist;
};
struct nslEmitter {
  bool used,autoRelease,isALineEmitter; nslEmitterId myId;
  V startPosition,endPosition,position; fifo_queue<nslSoundId> emittedSounds;
};
struct nslSystem {
  M listenerPo; nslSource sourceSlots[512]; nslSound soundSlots[256];
  nslEmitter emitterSlots[256]; U sourceSlotsUsedCount,soundSlotsUsedCount,emitterSlotsUsedCount;
  I firstInit,initialized; U numBanks; fifo_queue<nslSoundId> queuedSounds;
  nslSpeakerModeEnum speakerMode; nslOutputModeEnum outputMode;
  nslLanguageEnum language; nslPs2CdDvdMode cdDvdMode; Q lastClock;
  bool on,proview,finalizeSourcesEnabled;
  float sfxVolume,ambientVolume,musicVolume,voiceVolume,movieVolume,user1Volume,user2Volume,masterVolume,dampenLevel;
  char rootDir[32];
};
extern nslSystem nsl; extern char *nslLanguageStr[];
extern const char ni[], empty[];
void nslFatal(const char *,...); void nslReleaseAllSounds(); void _nslReleaseAllSources();
void _nslResetInternal(_nslClearBehaviour); bool nslPopBank();
int nslPs2GasRpc(int,const char *,int,int,int,int);
__asm__(".equ nsl,0x0049B5F0"); __asm__(".equ nslLanguageStr,0x004A0FD0");
__asm__(".equ ni,0x0051BDC8"); __asm__(".equ empty,0x0051BDF8");
__asm__(".equ nslFatal__FPCce,0x00391420"); __asm__(".equ nslReleaseAllSounds__Fv,0x0038D3D0");
__asm__(".equ _nslReleaseAllSources__Fv,0x0038C3A8");
__asm__(".equ _nslResetInternal__F18_nslClearBehaviour,0x00390DA8");
__asm__(".equ nslPopBank__Fv,0x0038FE60"); __asm__(".equ nslPs2GasRpc__FiPCciiii,0x00391AC0");
inline __attribute__((always_inline)) void check() { if (!(nsl.initialized==1)) nslFatal(ni); }

bool nslReset( const char *soundListfile, nslLanguageEnum language )
{
  char realSoundListFile[256];
  char toGas[256];
  check();
  if (!nsl.initialized) return false;
  if (language != NSL_LANGUAGE_Z)
    nsl.language = language;
  char *pos = strchr(soundListfile, '\\');
  if (pos == NULL)
    strcpy(realSoundListFile, "LEVELS\\");
  else
    strcpy(realSoundListFile, "" );
  strcat(realSoundListFile, soundListfile);
  if (stricmp(".SND", soundListfile + strlen(soundListfile) - 4) != 0)
    strcat(realSoundListFile, ".SND");
  strcpy(toGas, nsl.rootDir);
  strcat(toGas, "\\");
  strcat(toGas, nslLanguageStr[nsl.language]);
  strcat(toGas, "\\");
  strcat(toGas, realSoundListFile);
  fflush(stdout);
  nslReleaseAllSounds();
  _nslReleaseAllSources();
  _nslResetInternal( NSL_CLEAR_RESET );
  while(nslPopBank());
  nslPs2GasRpc(0x10d0, empty, 0, 0, 0, 0 );
  nslPs2GasRpc(0x00ef, nsl.rootDir, 0, 0, 0, 0);
  nslPs2GasRpc(0x1003, empty, 0,0, 0, 0);
  if (nslPs2GasRpc(0x00e2, toGas, 0, 0, 0, 0) == 0)
  {
    nsl.on = false;
    return false;
  }
  if ( nsl.finalizeSourcesEnabled )
    nslPs2GasRpc(0x00e4, empty, 0, 0, 0, 0);
  for (int i=0; i < NSL_NUM_SOUNDS; i++)
    nsl.soundSlots[i].myId = i;
  for (int i=0; i < NSL_NUM_SOURCES; i++)
    nsl.sourceSlots[i].myId = i;
  for (int i=0; i < NSL_NUM_EMITTERS; i++)
    nsl.emitterSlots[i].myId = i;
  nslPs2GasRpc(0x10d0, empty, 0x3fff, 0, 0, 0 );
  nsl.numBanks++;
  nsl.on = true;
  return true;
}
